#include "window.h"
#include "journalpath.h"
#include <QtWidgets>
#include <QSqlQuery>
#include <QSqlError>
#include <QDesktopServices>
void Window::txtProfiles(){
 QDialog dialog(QApplication::activeModalWidget()?QApplication::activeModalWidget():this);dialog.setObjectName("txtProfiles");dialog.setWindowTitle("Fichiers TXT permanents et profils personnalisés");dialog.resize(1100,560);auto layout=new QVBoxLayout(&dialog);
 auto info=new QLabel("Chaque profil ajoute une destination permanente. Un capcode peut appartenir à plusieurs profils. Actif et Journal TXT doivent être ON pour ce capcode. Supprimer un profil ne supprime jamais son fichier.");info->setWordWrap(true);layout->addWidget(info);
 auto table=new QTableWidget(0,7);table->setObjectName("profileTable");table->setHorizontalHeaderLabels({"Actif","Nom du profil","Fichier TXT permanent","Parcourir","Capcodes associés","Ouvrir TXT","Dossier"});table->verticalHeader()->hide();table->verticalHeader()->setDefaultSectionSize(36);table->setColumnWidth(0,75);table->setColumnWidth(1,150);table->setColumnWidth(2,350);table->setColumnWidth(3,95);table->setColumnWidth(4,160);table->setColumnWidth(5,85);table->horizontalHeader()->setStretchLastSection(true);layout->addWidget(table,1);
 auto append=[&](qlonglong id,QString name,QString path,bool active,QVariantList members){int row=table->rowCount();table->insertRow(row);auto toggle=new QCheckBox(active?"ON":"OFF");toggle->setChecked(active);table->setCellWidget(row,0,toggle);connect(toggle,&QCheckBox::toggled,&dialog,[toggle](bool checked){toggle->setText(checked?"ON":"OFF");});auto title=new QTableWidgetItem(name);title->setData(Qt::UserRole,id);title->setData(Qt::UserRole+1,members);table->setItem(row,1,title);auto fileItem=new QTableWidgetItem(path);fileItem->setToolTip(path);table->setItem(row,2,fileItem);
  auto browse=new QPushButton("Parcourir…");table->setCellWidget(row,3,browse);connect(browse,&QPushButton::clicked,&dialog,[&,browse]{int r=-1;for(int n=0;n<table->rowCount();++n)if(table->cellWidget(n,3)==browse)r=n;if(r<0)return;QFileDialog picker(&dialog,"Fichier permanent du profil — ajout",table->item(r,2)->text(),"Texte (*.txt);;Tous les fichiers (*)");picker.setObjectName("profileFilePicker");picker.setAcceptMode(QFileDialog::AcceptSave);picker.setFileMode(QFileDialog::AnyFile);picker.setDefaultSuffix("txt");picker.setOption(QFileDialog::DontConfirmOverwrite,true);if(picker.exec()==QDialog::Accepted&&!picker.selectedFiles().isEmpty()){auto value=normalizedTxtPath(picker.selectedFiles().first());table->item(r,2)->setText(value);table->item(r,2)->setToolTip(value);}});
  auto membersButton=new QPushButton("Choisir les capcodes…");table->setCellWidget(row,4,membersButton);connect(membersButton,&QPushButton::clicked,&dialog,[&,membersButton]{int r=-1;for(int n=0;n<table->rowCount();++n)if(table->cellWidget(n,4)==membersButton)r=n;if(r<0)return;QDialog choice(&dialog);choice.setObjectName("profileCapcodes");choice.setWindowTitle("Capcodes du profil — sélection multiple");choice.resize(560,480);auto column=new QVBoxLayout(&choice);auto search=new QLineEdit;search->setObjectName("memberSearch");search->setPlaceholderText("Rechercher par capcode ou alias");column->addWidget(search);auto list=new QListWidget;list->setObjectName("memberList");column->addWidget(list);auto selected=table->item(r,1)->data(Qt::UserRole+1).toList();QSet<uint> present;QSqlQuery q("SELECT ric,alias FROM capcodes ORDER BY ric",db_);while(q.next()){uint ric=q.value(0).toUInt();present.insert(ric);auto item=new QListWidgetItem(QString("%1 — %2").arg(ric,7,10,QChar('0')).arg(q.value(1).toString()),list);item->setData(Qt::UserRole,ric);item->setFlags(Qt::ItemIsEnabled|Qt::ItemIsSelectable|Qt::ItemIsUserCheckable);item->setCheckState(selected.contains(QVariant(ric))?Qt::Checked:Qt::Unchecked);}q.finish();for(auto value:selected)if(!present.contains(value.toUInt())){auto item=new QListWidgetItem(QString("%1 — capcode absent (association conservée)").arg(value.toUInt(),7,10,QChar('0')),list);item->setData(Qt::UserRole,value);item->setCheckState(Qt::Checked);}connect(search,&QLineEdit::textChanged,&choice,[list](QString text){for(int i=0;i<list->count();++i)list->item(i)->setHidden(!list->item(i)->text().contains(text,Qt::CaseInsensitive));});auto buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);column->addWidget(buttons);connect(buttons,&QDialogButtonBox::accepted,&choice,&QDialog::accept);connect(buttons,&QDialogButtonBox::rejected,&choice,&QDialog::reject);if(choice.exec()==QDialog::Accepted){QVariantList values;for(int i=0;i<list->count();++i)if(list->item(i)->checkState()==Qt::Checked)values<<list->item(i)->data(Qt::UserRole);table->item(r,1)->setData(Qt::UserRole+1,values);membersButton->setToolTip("Associations sauvegardées avec Enregistrer");}});
  for(int c:{5,6}){auto open=new QPushButton(c==5?"Ouvrir TXT":"Ouvrir");table->setCellWidget(row,c,open);connect(open,&QPushButton::clicked,&dialog,[&,open,c]{for(int n=0;n<table->rowCount();++n)if(table->cellWidget(n,c)==open){auto path=normalizedTxtPath(table->item(n,2)->text());if(!absoluteTxtPath(path)||(c==5&&!QFileInfo(path).isFile())){QMessageBox::warning(&dialog,"Chemin","Fichier inaccessible :\n"+path);return;}auto target=c==5?path:QFileInfo(path).absolutePath();if(!QFileInfo::exists(target)||!QDesktopServices::openUrl(QUrl::fromLocalFile(target)))QMessageBox::warning(&dialog,"Ouverture","Impossible d’ouvrir :\n"+target);break;}});}
 };
 QSqlQuery q("SELECT id,name,path,enabled FROM txt_profiles ORDER BY id",db_);while(q.next()){QVariantList members;QSqlQuery a(db_);a.prepare("SELECT ric FROM txt_profile_capcodes WHERE profile_id=? ORDER BY ric");a.addBindValue(q.value(0));if(a.exec())while(a.next())members<<a.value(0).toUInt();a.finish();append(q.value(0).toLongLong(),q.value(1).toString(),q.value(2).toString(),q.value(3).toBool(),members);}q.finish();
 auto bar=new QHBoxLayout;auto add=new QPushButton("Ajouter un profil");auto remove=new QPushButton("Supprimer le profil (conserver le fichier)");bar->addWidget(add);bar->addWidget(remove);layout->addLayout(bar);connect(add,&QPushButton::clicked,&dialog,[&]{append(0,"Nouveau profil","",false,{});});connect(remove,&QPushButton::clicked,&dialog,[&]{if(table->currentRow()>=0)table->removeRow(table->currentRow());});
 auto buttons=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel);buttons->button(QDialogButtonBox::Save)->setText("Enregistrer");buttons->button(QDialogButtonBox::Cancel)->setText("Annuler");layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{bool transaction=false;try{
  struct Profile{qlonglong id;QString name,path;bool enabled;QVariantList members;};QVector<Profile> profiles;for(int r=0;r<table->rowCount();++r){Profile p{table->item(r,1)->data(Qt::UserRole).toLongLong(),table->item(r,1)->text().trimmed(),normalizedTxtPath(table->item(r,2)->text()),qobject_cast<QCheckBox*>(table->cellWidget(r,0))->isChecked(),table->item(r,1)->data(Qt::UserRole+1).toList()};if(p.name.isEmpty())throw std::runtime_error("Le profil doit avoir un nom.");if(p.enabled){auto error=validateTxtFile(p.path);if(!error.isEmpty())throw std::runtime_error((p.path+"\n"+error).toStdString());}profiles.push_back(p);}
  auto check=[](QSqlQuery& query){if(!query.exec())throw std::runtime_error(query.lastError().text().toStdString());};if(!db_.transaction())throw std::runtime_error(db_.lastError().text().toStdString());transaction=true;sql("DELETE FROM txt_profile_capcodes");sql("DELETE FROM txt_profiles");for(auto p:profiles){QSqlQuery insert(db_);insert.prepare("INSERT INTO txt_profiles(id,name,path,enabled) VALUES(?,?,?,?)");insert.addBindValue(p.id?QVariant(p.id):QVariant());insert.addBindValue(p.name);insert.addBindValue(p.path);insert.addBindValue(p.enabled);check(insert);qlonglong id=p.id?p.id:insert.lastInsertId().toLongLong();insert.finish();QSet<uint> used;for(auto ric:p.members)if(!used.contains(ric.toUInt())){used.insert(ric.toUInt());QSqlQuery a(db_);a.prepare("INSERT INTO txt_profile_capcodes(profile_id,ric) VALUES(?,?)");a.addBindValue(id);a.addBindValue(ric);check(a);a.finish();}}if(!db_.commit())throw std::runtime_error(db_.lastError().text().toStdString());transaction=false;dialog.accept();
 }catch(const std::exception& e){if(transaction)db_.rollback();QMessageBox::warning(&dialog,"Profils non enregistrés",QString::fromUtf8(e.what())+"\nLa saisie est conservée. Aucun fichier n’est supprimé.");}});dialog.exec();
}
